def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    opp_coops = n - opp_defects
    last_m, last_o = history[-1]

    # First few rounds: cooperate and only retaliate to clear defection.
    if n < 3:
        return 'C'

    # Detect opponent's recent behavior.
    recent = history[-8:] if n >= 8 else history
    recent_opp_d = sum(1 for _, o in recent if o == 'D')
    recent_opp_c = len(recent) - recent_opp_d
    recent_my_d = sum(1 for m, _ in recent if m == 'D')

    # Persistently defecting opponent: stop feeding them, but occasionally probe.
    if opp_defects >= n * 0.85:
        if n > 20 and rng.random() < 0.05:
            return 'C'
        return 'D'

    # Very cooperative opponent: keep cooperation, avoid needless destabilization.
    if opp_defects == 0:
        # Rare late-game probe only if we have been reliably cooperative.
        if n > 30 and n % 20 == 0 and my_defects < 2:
            return 'D'
        return 'C'

    # Endgame: if opponent has been reliably cooperative, keep cooperating.
    if n >= 90:
        if opp_defects <= max(2, n // 20):
            return 'C'
        if opp_defects > opp_coops:
            return 'D'

    # If opponent just cooperated, mostly cooperate; occasionally exploit
    # only against an opponent that has shown itself forgiving of our defections.
    if last_o == 'C':
        if last_m == 'D' and opp_defects == 0:
            return 'C'
        # Rare probe against very forgiving cooperative opponents.
        if n > 15 and recent_opp_d == 0 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Opponent just defected. Decide between retaliation and repair.
    # Count consecutive opponent defections.
    streak_o = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_o += 1
        else:
            break

    # Count consecutive my defections.
    streak_m = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            streak_m += 1
        else:
            break

    # If opponent has been mostly cooperative, treat this as a temporary slip:
    # retaliate once, then forgive to restore mutual cooperation.
    if opp_defects <= max(2, n // 12):
        if streak_o >= 2:
            # They keep defecting; give a clear punishment then offer repair.
            if streak_o == 2 and rng.random() < 0.6:
                return 'C'
            return 'D'
        if last_m == 'D':
            # We already retaliated; return to cooperation to avoid a loop.
            return 'C'
        return 'D'

    # Moderate defection rate: firm tit-for-tat with periodic forgiveness.
    if opp_defects > n * 0.35:
        # Defect heavily, but try occasional repair when mutual defection has just occurred.
        if last_m == 'D' and streak_m >= 2 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Intermediate region: short punishment followed by renewed cooperation.
    if streak_o >= 3:
        # Long defection streak: punish, but break cycles periodically.
        if streak_m >= 2 and rng.random() < 0.3:
            return 'C'
        return 'D'

    if last_m == 'D':
        # We already punished once; return to cooperation.
        return 'C'

    # First defection after cooperation: retaliate once.
    return 'D'
